using System.Text.Json;
using LlamaApp.Llama;
using Xunit;

namespace LlamaApp.LlamaCpp.Tests;

/// <summary>
/// Unit tests for <see cref="LlamaManager.ExtractFailureDetail"/>: the
/// <c>download_failed</c> SSE payload is inspected for a human-readable error
/// string and everything else — including llama.cpp master's current bare
/// <c>data:{}</c> and an absent <c>data</c> field — yields <c>null</c> rather
/// than throwing or fabricating text.
/// </summary>
public class SseFailureExtractionTests
{
    private static string? Extract(string json)
    {
        using var doc = JsonDocument.Parse(json);
        return LlamaManager.ExtractFailureDetail(doc.RootElement);
    }

    [Fact]
    public void Absent_Data_Yields_Null()
    {
        // ParseSseStreamAsync hands a default (Undefined) JsonElement when the
        // event has no "data" field — TryGetProperty would throw on it.
        Assert.Null(LlamaManager.ExtractFailureDetail(default));
    }

    [Fact]
    public void Empty_Data_Object_Yields_Null()
        // llama.cpp master sends download_failed with data:{} — no error text.
        => Assert.Null(Extract("{}"));

    [Fact]
    public void String_Error_Field_Is_Extracted()
        => Assert.Equal("boom", Extract("""{"error":"boom"}"""));

    [Fact]
    public void Nested_Error_Message_Is_Extracted()
        => Assert.Equal("nested boom", Extract("""{"error":{"message":"nested boom"}}"""));

    [Fact]
    public void Top_Level_Message_Field_Is_Extracted()
        => Assert.Equal("top boom", Extract("""{"message":"top boom"}"""));

    [Fact]
    public void String_Error_Wins_Over_Message()
        => Assert.Equal("err", Extract("""{"error":"err","message":"msg"}"""));

    [Theory]
    [InlineData("""{"error":123}""")]
    [InlineData("""{"error":["a","b"]}""")]
    [InlineData("""{"error":{"message":42}}""")]
    [InlineData("""{"error":{"code":42}}""")]
    [InlineData("""{"message":{"a":1}}""")]
    [InlineData("""{"message":true}""")]
    [InlineData("""{"error":""}""")]
    [InlineData("""{"error":"   "}""")]
    [InlineData("""{"message":"\n\t"}""")]
    [InlineData("""[1,2,3]""")]
    [InlineData("""42""")]
    public void Non_String_Blank_Or_Non_Object_Payloads_Yield_Null(string json)
        => Assert.Null(Extract(json));

    [Fact]
    public void Malformed_Shapes_Never_Throw()
    {
        // A nested error object whose message is itself an object (not a
        // string) must fall through to null, not throw.
        Assert.Null(Extract("""{"error":{"message":{"deep":true}},"message":null}"""));
    }
}

using LlamaApp.Llama;
using Xunit;

namespace LlamaApp.LlamaCpp.Tests;

/// <summary>
/// Tests for the Settings "Remove Llama Files" action's core. The install dir
/// is the SHARED WindowsApps folder — home of every packaged app's execution
/// aliases (winget.exe, python.exe, ...) — so the deletion must remove exactly
/// the names install.ps1 can leave there and never anything else. (The button
/// used to wipe the folder's entire contents, destroying other apps' aliases.)
/// </summary>
public sealed class ManagedInstallEmptyTests : IDisposable
{
    private readonly string _root;

    public ManagedInstallEmptyTests()
    {
        _root = Path.Combine(Path.GetTempPath(), "llama-install-empty-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_root);
    }

    public void Dispose()
    {
        try { Directory.Delete(_root, recursive: true); } catch { /* best effort */ }
    }

    [Fact]
    public void RemovesOnlyTheKnownLlamaArtifacts()
    {
        // Llama's files: the binary plus everything older installers dropped.
        foreach (var name in LlamaManager.ManagedInstallArtifacts)
            File.WriteAllText(Path.Combine(_root, name), "llama data");
        // Other apps' execution aliases — must survive untouched.
        File.WriteAllText(Path.Combine(_root, "winget.exe"), "foreign");
        File.WriteAllText(Path.Combine(_root, "python.exe"), "foreign");
        Directory.CreateDirectory(Path.Combine(_root, "OtherApp"));
        File.WriteAllText(Path.Combine(_root, "OtherApp", "tool.exe"), "foreign");

        var (deleted, failed) = LlamaManager.EmptyManagedInstall(_root);

        Assert.Equal(0, failed);
        Assert.Equal(LlamaManager.ManagedInstallArtifacts.Count, deleted);
        foreach (var name in LlamaManager.ManagedInstallArtifacts)
            Assert.False(File.Exists(Path.Combine(_root, name)), $"{name} should be gone");
        Assert.True(File.Exists(Path.Combine(_root, "winget.exe")), "foreign alias must survive");
        Assert.True(File.Exists(Path.Combine(_root, "python.exe")), "foreign alias must survive");
        Assert.True(File.Exists(Path.Combine(_root, "OtherApp", "tool.exe")), "foreign subdir must survive");
    }

    [Fact]
    public void EmptyDirectory_IsANoOp()
    {
        var (deleted, failed) = LlamaManager.EmptyManagedInstall(_root);

        Assert.Equal(0, deleted);
        Assert.Equal(0, failed);
    }

    [Fact]
    public void ArtifactList_ContainsTheBinary_AndOnlyLlamaOwnedNames()
    {
        Assert.Contains("llama.exe", LlamaManager.ManagedInstallArtifacts);
        // Sanity: nothing generic in the list — every name is llama-owned so
        // the shared-folder deletion can never hit another app's file.
        foreach (var name in LlamaManager.ManagedInstallArtifacts)
        {
            Assert.True(
                name.StartsWith("llama.", StringComparison.OrdinalIgnoreCase) ||
                name.EndsWith("-probe.exe", StringComparison.OrdinalIgnoreCase) ||
                name is "unzstd.exe" or "featcode.exe" or "tmp.zst",
                $"unexpected non-llama artifact in the list: {name}");
        }
    }

    [Fact]
    public void ScratchDir_IsRemovedEntirely_WhenPresent()
    {
        var scratch = Path.Combine(_root, "llama-app");
        Directory.CreateDirectory(Path.Combine(scratch, "sub"));
        File.WriteAllText(Path.Combine(scratch, "tmp.zst"), "partial download");
        File.WriteAllText(Path.Combine(scratch, "sub", "probe.exe"), "probe");

        LlamaManager.DeleteInstallScratch(scratch);

        Assert.False(Directory.Exists(scratch));
    }

    [Fact]
    public void ScratchDir_Missing_IsANoOp()
    {
        var scratch = Path.Combine(_root, "no-such-scratch");

        LlamaManager.DeleteInstallScratch(scratch); // must not throw

        Assert.False(Directory.Exists(scratch));
    }

    [Fact]
    public void ScratchDir_IsTheLlamaAppFolderUnderLocalAppData()
    {
        var expected = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "llama-app");
        Assert.Equal(expected, LlamaManager.InstallScratchDir);
    }
}

using System.Text;
using LlamaApp.Common;
using Xunit;

namespace LlamaApp.LlamaCpp.Tests;

/// <summary>
/// Tests the installer provenance policy. The app executes the downloaded
/// <c>install.ps1</c> with <c>-ExecutionPolicy Bypass</c>, so every check here
/// is a barrier between a hostile/compromised endpoint and arbitrary code
/// execution: exact URL, no redirects, bounded size, and a hash pin for
/// unattended installs.
/// </summary>
public class InstallScriptIntegrityTests
{
    private static readonly Uri Good = new(InstallScriptIntegrity.ExpectedScriptUrl);

    // ---- ValidateResponse ----

    [Fact]
    public void Accepts_Direct_200_From_Expected_Url()
    {
        Assert.Equal(
            InstallScriptVerdict.Ok,
            InstallScriptIntegrity.ValidateResponse(200, Good, 5636));
    }

    [Fact]
    public void Accepts_Unknown_ContentLength()
    {
        // Chunked responses carry no Content-Length; the copy loop still bounds them.
        Assert.Equal(
            InstallScriptVerdict.Ok,
            InstallScriptIntegrity.ValidateResponse(200, Good, null));
    }

    [Theory]
    [InlineData(301)]
    [InlineData(302)]
    [InlineData(307)]
    [InlineData(308)]
    public void Refuses_Redirects_Instead_Of_Following(int status)
    {
        Assert.Equal(
            InstallScriptVerdict.Redirected,
            InstallScriptIntegrity.ValidateResponse(status, Good, null));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(403)]
    [InlineData(404)]
    [InlineData(500)]
    public void Refuses_Non200(int status)
    {
        Assert.Equal(
            InstallScriptVerdict.HttpError,
            InstallScriptIntegrity.ValidateResponse(status, Good, null));
    }

    [Theory]
    [InlineData("https://evil.example/install.ps1")]
    [InlineData("https://llama.app.evil.example/install.ps1")]
    [InlineData("http://llama.app/install.ps1")]
    [InlineData("https://llama.app:8443/install.ps1")]
    [InlineData("https://llama.app/other.ps1")]
    [InlineData("https://llama.app/install.ps1/extra")]
    [InlineData("https://llama.app")]
    public void Refuses_Unexpected_Uri(string uri)
    {
        Assert.Equal(
            InstallScriptVerdict.WrongUri,
            InstallScriptIntegrity.ValidateResponse(200, new Uri(uri), null));
    }

    [Fact]
    public void Refuses_Null_Final_Uri()
    {
        Assert.Equal(
            InstallScriptVerdict.WrongUri,
            InstallScriptIntegrity.ValidateResponse(200, null, null));
    }

    [Fact]
    public void Refuses_Declared_Size_Over_Limit()
    {
        Assert.Equal(
            InstallScriptVerdict.TooLarge,
            InstallScriptIntegrity.ValidateResponse(200, Good, InstallScriptIntegrity.MaxBytes + 1));
        Assert.Equal(
            InstallScriptVerdict.TooLarge,
            InstallScriptIntegrity.ValidateResponse(200, Good, 0));
    }

    // ---- IsExpectedUri ----

    [Theory]
    [InlineData("https://llama.app/install.ps1", true)]
    [InlineData("HTTPS://LLAMA.APP/install.ps1", true)]
    [InlineData("https://llama.app:443/install.ps1", true)]
    [InlineData("https://llama.app/Install.ps1", false)]
    [InlineData("https://cdn.llama.app/install.ps1", false)]
    [InlineData("https://llama.app/install.ps1?x=1", false)]
    public void IsExpectedUri_Checks(string uri, bool expected)
    {
        Assert.Equal(expected, InstallScriptIntegrity.IsExpectedUri(new Uri(uri)));
    }

    // ---- ValidateHash ----

    [Fact]
    public void Unpinned_When_No_Pin_Configured()
    {
        Assert.Equal(
            InstallScriptVerdict.Unpinned,
            InstallScriptIntegrity.ValidateHash("abc123", pinned: null));
        Assert.Equal(
            InstallScriptVerdict.Unpinned,
            InstallScriptIntegrity.ValidateHash("abc123", pinned: "   "));
    }

    [Fact]
    public void Matches_Pin_CaseInsensitively()
    {
        Assert.Equal(
            InstallScriptVerdict.Ok,
            InstallScriptIntegrity.ValidateHash("ABCDEF", pinned: "abcdef"));
    }

    [Fact]
    public void Mismatched_Pin_Is_Fatal()
    {
        Assert.Equal(
            InstallScriptVerdict.HashMismatch,
            InstallScriptIntegrity.ValidateHash("abcdef", pinned: "123456"));
        Assert.Equal(
            InstallScriptVerdict.HashMismatch,
            InstallScriptIntegrity.ValidateHash(null, pinned: "123456"));
    }

    // ---- Sha256Hex ----

    [Fact]
    public void Sha256Hex_Matches_Known_Vector()
    {
        // SHA-256("abc")
        Assert.Equal(
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
            InstallScriptIntegrity.Sha256Hex(Encoding.ASCII.GetBytes("abc")));
    }

    // ---- ReadBoundedAsync ----

    [Fact]
    public async Task ReadBounded_Returns_Under_Limit()
    {
        var data = Encoding.ASCII.GetBytes("hello");
        using var stream = new MemoryStream(data);
        Assert.Equal(data, await InstallScriptIntegrity.ReadBoundedAsync(stream, maxBytes: 1024));
    }

    [Fact]
    public async Task ReadBounded_Throws_Over_Limit()
    {
        var data = new byte[2048];
        using var stream = new MemoryStream(data);
        await Assert.ThrowsAsync<InvalidDataException>(
            () => InstallScriptIntegrity.ReadBoundedAsync(stream, maxBytes: 1024));
    }

    // ---- EncodeCommand (fileless -EncodedCommand payload) ----

    [Fact]
    public void EncodeCommand_Round_Trips_Through_PowerShell_Decoding()
    {
        // -EncodedCommand expects base64(UTF-16LE(script)); decoding the
        // payload the way powershell.exe does must return the exact script
        // text — no BOM, no encoding drift for non-ASCII content.
        const string script = "Write-Output 'h\u00e9llo'\r\nexit 0";
        var payload = InstallScriptIntegrity.EncodeCommand(Encoding.UTF8.GetBytes(script));
        var decoded = Encoding.Unicode.GetString(Convert.FromBase64String(payload));
        Assert.Equal(script, decoded);
    }

    [Fact]
    public void EncodeCommand_Honors_Utf8_Bom()
    {
        var withBom = new byte[] { 0xEF, 0xBB, 0xBF }.Concat(Encoding.UTF8.GetBytes("exit 0")).ToArray();
        var payload = InstallScriptIntegrity.EncodeCommand(withBom);
        Assert.Equal("exit 0", Encoding.Unicode.GetString(Convert.FromBase64String(payload)));
    }

    [Fact]
    public void EncodeCommand_Refuses_Oversized_Script()
    {
        // Well under MaxBytes (the transport cap) but far past what a
        // CreateProcess command line can carry — the refusal must be a
        // clean error, never a silent temp-file fallback.
        var oversize = Encoding.ASCII.GetBytes(new string('x', 20_000));
        Assert.Throws<InvalidDataException>(
            () => InstallScriptIntegrity.EncodeCommand(oversize));
    }

    [Fact]
    public void EncodeCommand_Accepts_Realistic_Install_Script_Size()
    {
        // The real install.ps1 is a few KB — that must always fit.
        var typical = Encoding.ASCII.GetBytes(new string('x', 4_000));
        Assert.True(
            InstallScriptIntegrity.EncodeCommand(typical).Length <=
            InstallScriptIntegrity.MaxEncodedCommandChars);
    }
}

using LlamaApp.Common;
using Xunit;

namespace LlamaApp.LlamaCpp.Tests;

/// <summary>
/// Tests for the local-server access policy: when the llama server is bound
/// beyond loopback it needs an app-generated API key, otherwise it is an open
/// control API (model download/load/delete, chat) on the network.
/// </summary>
public sealed class ServerAuthTests
{
    [Theory]
    [InlineData("127.0.0.1", false)]
    [InlineData("127.0.0.5", false)]   // any loopback address stays local
    [InlineData("", false)]
    [InlineData(null, false)]
    [InlineData("not-an-ip", false)]
    [InlineData("::1", false)]          // IPv6 is not a valid bind here anyway
    [InlineData("0.0.0.0", true)]
    [InlineData("192.168.1.42", true)]
    [InlineData("10.0.0.5", true)]
    public void RequiresApiKey_MatchesWhetherBindExceedsThisMachine(string? address, bool expected)
    {
        Assert.Equal(expected, ServerAuth.RequiresApiKey(address));
    }

    [Fact]
    public void GenerateApiKey_Is64LowercaseHexChars()
    {
        var key = ServerAuth.GenerateApiKey();

        Assert.Equal(64, key.Length);
        Assert.All(key, c => Assert.True(c is >= '0' and <= '9' or >= 'a' and <= 'f', $"non-hex char: {c}"));
    }

    [Fact]
    public void GenerateApiKey_IsUnique()
    {
        Assert.NotEqual(ServerAuth.GenerateApiKey(), ServerAuth.GenerateApiKey());
    }
}

using LlamaApp.Common;
using Xunit;

namespace LlamaApp.LlamaCpp.Tests;

/// <summary>
/// Tests for the family-name brand detection (Common) that keeps local models' logo
/// tiles from rendering empty (an imported .gguf, a folder-enrolled model, a
/// Hub repo outside the catalog — none of them have a catalog brand). Known
/// family keywords match inside the model's name; the mapping must mirror the
/// bundled logos' families, stay case-insensitive, and NOT misfire on the
/// lookalikes (GPTQ the quantization format is not GPT the family).
/// </summary>
public sealed class LocalBrandFromNameTests
{
    // ---- known families ----

    [Theory]
    [InlineData("gemma-3-1b-it-qat-Q4_0", "gemma")]        // enrolled/import stem
    [InlineData("Gemma-4-E4B-it-Q4_0", "gemma")]            // case-insensitive
    [InlineData("Qwen3.8-27B-BF16", "qwen")]               // digit-suffixed family
    [InlineData("qwen3-coder-30b", "qwen")]
    [InlineData("gpt-oss-20b-mxfp4", "gpt")]
    [InlineData("Mistral-7B-Instruct-v0.2", "mistral")]
    [InlineData("Ministral-8B-Instruct", "mistral")]
    [InlineData("devstral-small", "mistral")]
    [InlineData("GLM-4.7-Air-Q4_0", "z")]
    [InlineData("Nemotron-Super-49B", "nvidia")]
    [InlineData("ggml-org/gemma-3-1b-it-qat-GGUF:Q4_0", "gemma")] // full server id
    [InlineData("mimo-v2.6-9B", null)]
    [InlineData("Llama-3.2-1B-Instruct", null)]
    [InlineData("llama-8b", null)]
    [InlineData("MyPrivateFineTune-Q8_0", null)]
    [InlineData("", null)]
    [InlineData(null, null)]
    public void FamilyKeywords_MatchInsideTheName(string? name, string? expected)
    {
        Assert.Equal(expected, ModelBrandNames.BrandFromName(name));
    }

    // ---- the GPTQ lookalike ----

    [Theory]
    [InlineData("MyModel-GPTQ-4bit")]      // quantization format, not the family
    [InlineData("model_gptq")]
    [InlineData("GPTQ.gguf")]
    public void Gptq_TheQuantFormat_IsNotTheGptFamily(string name)
    {
        Assert.Null(ModelBrandNames.BrandFromName(name));
    }

    // ---- boundaries ----

    [Theory]
    [InlineData("gpt-oss-20b", "gpt")]     // hyphen boundary
    [InlineData("openai_gpt", "gpt")]       // underscore boundary
    [InlineData("deepseek-gpt4-alternative", "gpt")] // mid-name after a boundary
    public void WordBoundaries_AreRespected(string name, string? expected)
    {
        Assert.Equal(expected, ModelBrandNames.BrandFromName(name));
    }
}

using System.Text.Json;
using Xunit;

namespace LlamaApp.Tests;

/// <summary>
/// Tests for the persisted <c>Settings.MaxLoadedModels</c> value: new fields
/// must default to unlimited (<c>0</c>) and survive a JSON round-trip.
/// </summary>
public sealed class SettingsModelsMaxTests
{
    [Fact]
    public void MaxLoadedModels_DefaultsToUnlimited()
    {
        var settings = new Settings();

        Assert.Equal(0, settings.MaxLoadedModels);
    }

    [Fact]
    public void MaxLoadedModels_MissingFromSavedJson_DefaultsToUnlimited()
    {
        // A settings.json written before this field shipped has no
        // MaxLoadedModels property. Deserialization must leave it at 0, not
        // require the field.
        const string json = """{"ServerPort":9931,"IdleUnloadSeconds":-1}""";

        var settings = JsonSerializer.Deserialize<Settings>(json);

        Assert.NotNull(settings);
        Assert.Equal(0, settings.MaxLoadedModels);
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(4)]
    [InlineData(64)]
    public void MaxLoadedModels_RoundTripsThroughJson(int value)
    {
        var settings = new Settings { MaxLoadedModels = value };

        var json = JsonSerializer.Serialize(settings);
        var loaded = JsonSerializer.Deserialize<Settings>(json);

        Assert.NotNull(loaded);
        Assert.Equal(value, loaded.MaxLoadedModels);
        Assert.Contains("\"MaxLoadedModels\"", json);
    }
}

using System.Text.RegularExpressions;
using LlamaApp.Common;
using Xunit;

namespace LlamaApp.Tests;

/// <summary>
/// Contract for the shared HTTP User-Agent every client must attach:
/// <c>llama-win/<major.minor.patch> (<major.minor.build>; <arch>)</c>
/// — the app version from the entry assembly, the real Windows build, and
/// the <b>machine's native</b> architecture (not the process's: the app
/// ships an x64 build that runs emulated on ARM64 PCs, and a process-arch
/// token would report x64 for every ARM64 machine, hiding them from
/// backend statistics). This header is the only usage signal the app
/// emits (there is no telemetry), so its shape is pinned here.
/// </summary>
public class HttpUserAgentTests
{
    [Fact]
    public void Value_is_llama_win_version_with_windows_build_and_arch()
    {
        Assert.Matches(
            new Regex(@"^llama-win/\d+\.\d+\.\d+ \(\d+\.\d+\.\d+; (x64|x86|arm64|arm)\)$"),
            HttpUserAgent.Value);
    }

    [Fact]
    public void Value_reports_the_native_os_architecture()
    {
        // The arch token is exactly the native OS architecture (lowercased)
        // — on an ARM64 PC this is arm64 even though the process is x64
        // running under emulation.
        Assert.EndsWith(
            $"; {HttpUserAgent.NativeOsArchitecture().ToLowerInvariant()})",
            HttpUserAgent.Value);
    }

    [Fact]
    public void Value_is_stable_across_calls()
    {
        Assert.Equal(HttpUserAgent.Value, HttpUserAgent.Value);
    }

    [Fact]
    public void Value_is_not_one_of_the_old_user_agent_literals()
    {
        // Regression guards: the original bare "Llama/x" agent and the
        // telemetry-era "LlamaWindows/x.y.z" product — neither may return.
        Assert.DoesNotMatch(new Regex(@"^Llama/"), HttpUserAgent.Value);
        Assert.DoesNotMatch(new Regex(@"^LlamaWindows/"), HttpUserAgent.Value);
    }
}

using LlamaApp.Views;
using Xunit;

namespace LlamaApp.Tests;

/// <summary>
/// Unit tests for <see cref="ModelPresence.EffectivelyPresent"/> — the gate
/// behind hiding rows the disk no longer backs. The risks of hiding are
/// pinned here: busy models always keep their rows (a mid-download has no
/// file; a loaded model may have been deleted under a running child), and
/// everything with a findable file counts as present regardless of the
/// server's listing.
/// </summary>
public class ModelPresenceTests
{
    private static HashSet<string> Present(
        string[] serverIds, string[] busy, string[] onDisk)
        => ModelPresence.EffectivelyPresent(
            serverIds,
            id => busy.Contains(id, StringComparer.OrdinalIgnoreCase),
            id => onDisk.Contains(id, StringComparer.OrdinalIgnoreCase));

    [Fact]
    public void Listed_But_Fileless_Idle_Models_Are_Ghosts()
    {
        var present = Present(["ghost-Q4_0", "real-Q4_0"], [], ["real-Q4_0"]);

        Assert.Single(present);
        Assert.Contains("real-Q4_0", present);
    }

    [Theory]
    [InlineData("downloading")]   // no file yet by definition
    [InlineData("loading")]       // the child is starting
    [InlineData("loaded")]        // running — possibly deleted under it
    public void Busy_Models_Always_Keep_Their_Rows(string busyId)
    {
        var present = Present([busyId], [busyId], []);

        Assert.Contains(busyId, present);
    }

    [Fact]
    public void A_File_On_Disk_Keeps_The_Row_Even_When_Unlisted_By_Resolution_Heuristics()
        // "fileExists" is the app's own resolution — anything it finds is
        // present, full stop.
        => Assert.Contains(
            "here-Q4_0", Present(["here-Q4_0"], [], ["here-Q4_0"]));

    [Fact]
    public void Ids_The_Server_Does_Not_List_Are_Not_Present()
        => Assert.Empty(Present([], [], ["orphan-Q4_0"]));

    [Fact]
    public void Matching_Is_Case_Insensitive()
    {
        var present = Present(["Org/Repo:Q4_0"], [], ["ORG/REPO:q4_0"]);

        Assert.Single(present);
    }
}

using LlamaApp.Views;
using Xunit;

namespace LlamaApp.Tests;

/// <summary>
/// <see cref="ModelItem.RowDisplayName"/> — the row/header name without the
/// tag-carried parts (trailing "(quant)" suffix, standalone params token).
/// </summary>
public sealed class ModelItemDisplayNameTests
{
    [Theory]
    // The catalog shape: "Pretty Name (QUANT)" — both parts stripped.
    [InlineData("Gemma 3 1B (Q4_0)", "Q4_0", "1B", "Gemma 3")]
    [InlineData("GPT-OSS 20B (mxfp4)", "mxfp4", "20B", "GPT-OSS")]
    [InlineData("Gemma 4 E2B (Q4_K_M)", "Q4_K_M", "E2B", "Gemma 4")]
    // No quant suffix — the params token still goes.
    [InlineData("Gemma 3 1B", null, "1B", "Gemma 3")]
    // Params unknown — only the quant suffix is stripped.
    [InlineData("Gemma 3 1B (Q4_0)", "Q4_0", "", "Gemma 3 1B")]
    // A multi-word params phrase is stripped as a phrase.
    [InlineData("Ministral 3 3B Reasoning (Q4_K_M)", "Q4_K_M", "3B Reasoning", "Ministral 3")]
    // A params-looking substring inside a hyphenated slug is part of the
    // name, not a tag — it stays.
    [InlineData("Ministral-3-3B-Reasoning (Q4_K_M)", "Q4_K_M", "3B", "Ministral-3-3B-Reasoning")]
    [InlineData("Qwen3-4B", "Q4_K_M", "4B", "Qwen3-4B")]
    // Substring of a longer token ("11B") is not a match either.
    [InlineData("Gemma 3 11B (Q4_0)", "Q4_0", "1B", "Gemma 3 11B")]
    // The name IS the params token — stripping it would leave nothing.
    [InlineData("20B", null, "20B", "20B")]
    public void RowDisplayName_Strips_The_Tag_Carried_Parts(
        string name, string? quant, string parameters, string expected)
    {
        var item = new ModelItem { Name = name, Quant = quant, Parameters = parameters };

        Assert.Equal(expected, item.RowDisplayName);
    }

    [Fact]
    public void HasQuant_Tracks_The_Quant_Label()
    {
        Assert.True(new ModelItem { Quant = "Q4_0" }.HasQuant);
        Assert.False(new ModelItem { Quant = null }.HasQuant);
        Assert.False(new ModelItem { Quant = "" }.HasQuant);
    }
}

