/// <summary>
/// Unit tests for <see cref="ModelFileLocator"/> — the fallback that finds a
/// model's GGUF on disk when the server reports no path (the router /models
/// payload has none, so without it the details view can never read context
/// metadata). The locator probes two real-world cache layouts; each test
/// builds a tiny fake cache in a temp dir — no multi-GB fixtures.
/// </summary>
public sealed class ModelFileLocatorTests : IDisposable
{
    private readonly string _root;

    public ModelFileLocatorTests()
    {
        _root = Path.Combine(Path.GetTempPath(), "llama-locator-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_root);
    }

    public void Dispose()
    {
        try { Directory.Delete(_root, recursive: true); } catch { /* best effort */ }
    }

    private string HubFile(string repo, string snapshot, string fileName, int size = 100)
    {
        var dir = Path.Combine(_root, "models--" + repo.Replace("/", "--"), "snapshots", snapshot);
        Directory.CreateDirectory(dir);
        var path = Path.Combine(dir, fileName);
        File.WriteAllBytes(path, new byte[size]);
        return path;
    }

    private string FlatFile(string repo, string fileName, int size = 100)
    {
        var path = Path.Combine(_root, repo.Replace('/', '_') + "_" + fileName);
        File.WriteAllBytes(path, new byte[size]);
        return path;
    }

    private ModelFileLocator.LocatedModel? Find(string id) =>
        ModelFileLocator.TryFind(id, [_root]);

    [Fact]
    public void FindsModelInHubCacheLayout()
    {
        var expected = HubFile("mistralai/Ministral-3-3B-Reasoning-2512-GGUF", "abc123",
            "Ministral-3-3B-Reasoning-2512-Q4_K_M.gguf", size: 1234);

        var found = Find("mistralai/Ministral-3-3B-Reasoning-2512-GGUF:Q4_K_M");

        Assert.NotNull(found);
        Assert.Equal(expected, found!.PrimaryFilePath);
        Assert.Equal(1234, found.TotalSizeBytes);
    }

    [Fact]
    public void FindsModelInFlatLlamaCppCacheLayout()
    {
        var expected = FlatFile("ggml-org/gemma-3-270m-it-qat-GGUF",
            "gemma-3-270m-it-qat-Q4_0.gguf", size: 777);

        var found = Find("ggml-org/gemma-3-270m-it-qat-GGUF:Q4_0");

        Assert.NotNull(found);
        Assert.Equal(expected, found!.PrimaryFilePath);
        Assert.Equal(777, found.TotalSizeBytes);
    }

    [Fact]
    public void QuantSelectsAmongTheReposFiles()
    {
        HubFile("org/model-GGUF", "sha", "model-Q4_K_M.gguf");
        var q8 = HubFile("org/model-GGUF", "sha", "model-Q8_0.gguf");

        var found = Find("org/model-GGUF:Q8_0");

        Assert.NotNull(found);
        Assert.Equal(q8, found!.PrimaryFilePath);
    }

    [Fact]
    public void MmprojVisionProjectorNeverMatches()
    {
        HubFile("org/vision-GGUF", "sha", "vision-BF16-mmproj.gguf");

        Assert.Null(Find("org/vision-GGUF:BF16"));
    }

    [Fact]
    public void MultiShardModelSumsAllShardsAndReadsTheFirst()
    {
        var shard1 = HubFile("org/big-GGUF", "sha", "big-Q4_K_M-00001-of-00002.gguf", size: 100);
        HubFile("org/big-GGUF", "sha", "big-Q4_K_M-00002-of-00002.gguf", size: 50);

        var found = Find("org/big-GGUF:Q4_K_M");

        Assert.NotNull(found);
        Assert.Equal(shard1, found!.PrimaryFilePath); // the header lives in shard 1
        Assert.Equal(150, found.TotalSizeBytes);
    }

    [Fact]
    public void BareRepoIdMatchesAnyModelFile()
    {
        // Mid-download the server ids the model by its bare repo (quant unresolved).
        var expected = HubFile("org/model-GGUF", "sha", "model-Q4_K_M.gguf");

        var found = Find("org/model-GGUF");

        Assert.NotNull(found);
        Assert.Equal(expected, found!.PrimaryFilePath);
    }

    [Fact]
    public void UnknownModelReturnsNull()
    {
        HubFile("org/present-GGUF", "sha", "present-Q4_K_M.gguf");

        Assert.Null(Find("org/absent-GGUF:Q4_K_M"));
        Assert.Null(Find("org/present-GGUF:Q8_0")); // right repo, wrong quant
    }

    [Fact]
    public void MissingDirectoriesAreSkippedNotThrown()
    {
        // No cache content at all — just must not throw.
        Assert.Null(Find("org/model-GGUF:Q4_K_M"));
        Assert.Null(ModelFileLocator.TryFind("org/model-GGUF:Q4_K_M",
            [Path.Combine(_root, "does-not-exist")]));
    }

    [Fact]
    public void GarbageIdsReturnNull()
    {
        Assert.Null(Find(""));
        Assert.Null(Find("   "));
        Assert.Null(Find(":Q4_K_M"));
    }
}

using System.Text.Json;
using LlamaApp.Views;
using Xunit;

namespace LlamaApp.Tests;

/// <summary>
/// Tests for the sample API request strings: they must target the server's
/// connect address (which follows the Settings listen choice) rather than a
/// hard-coded localhost, so a server bound to a specific interface produces a
/// URL that actually reaches it.
/// </summary>
public sealed class ApiRequestPresentationTests
{
    [Fact]
    public void BuildCurlCommand_UsesTheGivenAddress()
    {
        var cmd = ApiRequestPresentation.BuildCurlCommand(
            "192.168.1.42", 9931, "unsloth/Qwen3-4B-GGUF:Q4_K_M");

        Assert.StartsWith("curl ", cmd);
        Assert.Contains("http://192.168.1.42:9931/v1/chat/completions", cmd);
        Assert.Contains("unsloth/Qwen3-4B-GGUF:Q4_K_M", cmd);
    }

    [Fact]
    public void BuildWebUiUrl_UsesTheGivenAddress()
    {
        var url = ApiRequestPresentation.BuildWebUiUrl(
            "10.0.0.5", 8080, "ggml-org/gemma-3-4b-it-GGUF:Q4_K_M");

        Assert.Equal(
            "http://10.0.0.5:8080?model=ggml-org%2Fgemma-3-4b-it-GGUF%3AQ4_K_M",
            url);
    }

    [Fact]
    public void BuildWebUiUrl_EscapesTheModelId()
    {
        var url = ApiRequestPresentation.BuildWebUiUrl(
            "127.0.0.1", 9931, "a/b:Q4_K_M");

        Assert.Equal("http://127.0.0.1:9931?model=a%2Fb%3AQ4_K_M", url);
    }

    // ---- Injection resistance: model ids are remote data ----

    [Fact]
    public void BuildCurlCommand_JsonEscapesTheModelId()
    {
        // A raw-interpolated body would let this append extra JSON fields.
        var id = "evil\",\"x\":1,\"y\":\"";
        var cmd = ApiRequestPresentation.BuildCurlCommand("127.0.0.1", 9931, id);

        var json = ExtractDataPayload(cmd);
        using var doc = JsonDocument.Parse(json);
        Assert.Equal(id, doc.RootElement.GetProperty("model").GetString());
        Assert.False(doc.RootElement.TryGetProperty("x", out _));
        Assert.False(doc.RootElement.TryGetProperty("y", out _));
    }

    [Fact]
    public void BuildCurlCommand_SingleQuotesThePayload()
    {
        var cmd = ApiRequestPresentation.BuildCurlCommand("127.0.0.1", 9931, "a/b:Q4_K_M");

        // POSIX single quotes stop $(...)/backtick expansion on paste.
        Assert.Contains("-d '", cmd);
        Assert.EndsWith("'", cmd);
    }

    /// <summary>Pulls the shell-quoted <c>-d</c> payload back out for parsing.</summary>
    private static string ExtractDataPayload(string cmd)
    {
        const string marker = "-d '";
        var start = cmd.IndexOf(marker, StringComparison.Ordinal) + marker.Length;
        return cmd[start..cmd.LastIndexOf('\'')];
    }

    // ---- API-key threading (non-loopback binds) ----

    [Fact]
    public void BuildWebUiUrl_NeverCarriesTheApiKey()
    {
        // llama.cpp's WebUI reads its key from a typed dialog (no query form);
        // a ?api_key= would be ignored by the page and leak into browser
        // history, caches and server logs. The key must never be in a URL.
        var url = ApiRequestPresentation.BuildWebUiUrl(
            "192.168.1.42", 9931, "a/b:Q4_K_M");

        Assert.Equal("http://192.168.1.42:9931?model=a%2Fb%3AQ4_K_M", url);
        Assert.DoesNotContain("api_key", url);
    }

    [Fact]
    public void BuildCurlCommand_WithKey_IncludesBearerHeader()
    {
        var cmd = ApiRequestPresentation.BuildCurlCommand(
            "192.168.1.42", 9931, "a/b:Q4_K_M", apiKey: "cafe1234");

        Assert.Contains("-H \"Authorization: Bearer cafe1234\"", cmd);
        // The header sits before the payload so the request is well-formed.
        Assert.True(cmd.IndexOf("Authorization") < cmd.IndexOf("-d "));
    }

    [Fact]
    public void BuildCurlCommand_WithoutKey_HasNoBearerHeader()
    {
        var cmd = ApiRequestPresentation.BuildCurlCommand(
            "127.0.0.1", 9931, "a/b:Q4_K_M", apiKey: null);

        Assert.DoesNotContain("Authorization", cmd);
    }
}

using Xunit;

namespace LlamaApp.LlamaCpp.Tests;

/// <summary>
/// Tests for the spec-decoding entries of the <c>--models-preset</c> INI
/// (issue #97): the router's INI parser accepts sections named by the model
/// id with keys spelled as the CLI long options, and the child needs
/// <c>spec-type</c> to fetch and wire the draft sidecar. These tests pin the
/// exact rendered shape — including how a model with both a context length
/// and a spec type merges into ONE section (a duplicate section would
/// overwrite, not merge, in a naive INI parser).
/// </summary>
public sealed class ModelsPresetSpecTests
{
    private static readonly IReadOnlyDictionary<string, int> NoContexts =
        new Dictionary<string, int>();

    [Fact]
    public void SpecOnlyModel_GetsItsOwnSection()
    {
        var ini = Render(
            contexts: NoContexts,
            specs: new Dictionary<string, string>
            {
                ["ggml-org/Qwen3.8-27B-GGUF:Q4_0"] = "draft-dflash",
            });

        Assert.Equal(
            "[ggml-org/Qwen3.8-27B-GGUF:Q4_0]\n" +
            "spec-type = draft-dflash\n\n",
            ini);
    }

    [Fact]
    public void ContextAndSpec_MergeIntoOneSection()
    {
        var ini = Render(
            contexts: new Dictionary<string, int> { ["org/repo:Q4_0"] = 8192 },
            specs: new Dictionary<string, string> { ["org/repo:Q4_0"] = "draft-mtp" });

        Assert.Equal(
            "[org/repo:Q4_0]\n" +
            "ctx-size = 8192\n" +
            "spec-type = draft-mtp\n\n",
            ini);
    }

    [Fact]
    public void NegativeCacheEntries_AreNotRendered()
    {
        // "" means "checked, the repo ships no head" — never an INI entry
        // (an empty spec-type would fault the child's arg parsing).
        var ini = Render(
            contexts: new Dictionary<string, int> { ["org/repo:Q4_0"] = 4096 },
            specs: new Dictionary<string, string>
            {
                ["org/repo:Q4_0"] = "",
                ["org/other:Q8_0"] = "",
            });

        Assert.Equal(
            "[org/repo:Q4_0]\n" +
            "ctx-size = 4096\n\n",
            ini);
    }

    [Fact]
    public void NoEntriesAtAll_RendersEmpty()
    {
        Assert.Equal("", Render(contexts: NoContexts, specs: new Dictionary<string, string>()));
        Assert.Equal("", Render(contexts: NoContexts,
            specs: new Dictionary<string, string> { ["x"] = "" }));
    }

    [Fact]
    public void InvalidContextEntries_AreSkippedLikeBefore()
    {
        var ini = Render(
            contexts: new Dictionary<string, int>
            {
                ["org/repo:Q4_0"] = 0,
                ["org/repo2:Q4_0"] = -5,
                [""] = 100,
            },
            specs: new Dictionary<string, string> { ["org/repo:Q4_0"] = "draft-dspark" });

        Assert.Equal(
            "[org/repo:Q4_0]\n" +
            "spec-type = draft-dspark\n\n",
            ini);
    }

    [Fact]
    public void SectionNamesWithBrackets_AreSkipped()
    {
        // A .gguf filename may legally contain ']' / '[' — rendering one raw
        // would end the section early ("[x]junk]") and silently apply the
        // preset to the wrong model. The whole entry is dropped instead.
        var ini = Render(
            contexts: new Dictionary<string, int>
            {
                ["org/x]y:Q4_0"] = 8192,
                ["org/[z:Q4_0"] = 4096,
            },
            specs: new Dictionary<string, string> { ["org/x]y:Q4_0"] = "draft-mtp" });

        Assert.Equal("", ini);
    }

    [Fact]
    public void SectionNamesWithControlCharacters_AreSkipped()
    {
        // A newline would inject whole INI lines — settings entries are
        // hand-editable even though filenames can't carry CR/LF.
        var ini = Render(
            contexts: new Dictionary<string, int> { ["org/x\ny:Q4_0"] = 8192 },
            specs: new Dictionary<string, string> { ["org/x\r\ny:Q4_0"] = "draft-mtp" });

        Assert.Equal("", ini);
    }

    [Fact]
    public void SpecValuesWithControlCharacters_AreDroppedButContextKept()
    {
        // The value must not be able to append arbitrary keys; the model's
        // ctx-size entry is still rendered, just without the spec line.
        var ini = Render(
            contexts: new Dictionary<string, int> { ["org/repo:Q4_0"] = 4096 },
            specs: new Dictionary<string, string>
            {
                ["org/repo:Q4_0"] = "draft-mtp\nctx-size = 999999",
            });

        Assert.Equal(
            "[org/repo:Q4_0]\n" +
            "ctx-size = 4096\n\n",
            ini);
    }

    private static string Render(
        IReadOnlyDictionary<string, int> contexts,
        IReadOnlyDictionary<string, string> specs) =>
        Llama.LlamaManager.RenderModelsPresetIni(contexts, specs);
}

using System.Text.Json;
using LlamaApp.Llama;
using Xunit;

namespace LlamaApp.LlamaCpp.Tests;

/// <summary>
/// Security tests for the two model-id sinks that take remote data:
/// <see cref="ModelFileLocator"/> (ids become filesystem paths) and
/// <see cref="LlamaManager.BuildModelRequestBody"/> (ids become JSON bodies).
/// Ids can originate in the llama.app catalog, Hub search results, or an
/// adopted server's <c>/models</c> payload, so neither may trust them raw.
/// </summary>
public sealed class ModelIdSafetyTests : IDisposable
{
    private readonly string _root;

    public ModelIdSafetyTests()
    {
        _root = Path.Combine(Path.GetTempPath(), "llama-idsafety-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_root);
    }

    public void Dispose()
    {
        try { Directory.Delete(_root, recursive: true); } catch { /* best effort */ }
    }

    // ---- IsSafeModelId ----

    [Theory]
    [InlineData("owner/repo")]
    [InlineData("owner/repo:Q4_K_M")]
    [InlineData("repo")]
    [InlineData("repo:q8_0")]
    [InlineData("TheBloke/Mistral-7B-Instruct-v0.2-GGUF:Q5_K_M")]
    [InlineData("unsloth/Qwen2.5-7B-Instruct-GGUF:IQ4_NL")]
    [InlineData("org/repo.name_v2-extra:Q4_0")]
    public void SafeIds_AreAccepted(string id)
    {
        Assert.True(ModelFileLocator.IsSafeModelId(id));
    }

    [Theory]
    [InlineData("..\\..\\..\\evil:Q4_K_M")]
    [InlineData("..\\..\\evil")]
    [InlineData("owner/../../etc:Q4_K_M")]
    [InlineData("../repo:Q4_K_M")]
    [InlineData("owner/repo/extra:Q4_K_M")]      // more than one slash
    [InlineData("owner\\repo:Q4_K_M")]           // backslash separator
    [InlineData("owner/repo:..")]                // traversal quant
    [InlineData("owner/repo:")]
    [InlineData("/")]
    [InlineData("owner/repo:*")]                 // wildcard
    [InlineData("owner/repo:Q4?")]
    [InlineData("owner/repo:Q4\u0000")]
    [InlineData("C:/Windows/System32:Q4_K_M")]
    [InlineData("")]
    [InlineData("   ")]
    [InlineData(null)]
    public void UnsafeIds_AreRejected(string? id)
    {
        Assert.False(ModelFileLocator.IsSafeModelId(id));
    }

    [Fact]
    public void TraversalId_DoesNotEscapeCacheRoot()
    {
        // Plant a GGUF one level ABOVE the cache root, then attempt the
        // classic backslash traversal. Without validation the id would
        // resolve out of the root and find it.
        var parent = Path.GetDirectoryName(_root)!;
        var outsideName = "llama-idsafety-outside-" + Guid.NewGuid().ToString("N") + ".gguf";
        var outside = Path.Combine(parent, outsideName);
        File.WriteAllBytes(outside, new byte[16]);
        try
        {
            // The id must be rejected outright, so no probing happens at all.
            Assert.False(ModelFileLocator.IsSafeModelId("..\\..\\evil"));
            Assert.Null(ModelFileLocator.TryFind("..\\..\\evil:Q4_K_M", [_root]));
            Assert.Null(ModelFileLocator.TryFind("owner/../../evil:Q4_K_M", [_root]));
        }
        finally
        {
            try { File.Delete(outside); } catch { /* best effort */ }
        }
    }

    [Fact]
    public void IsUnder_AcceptsRootAndDescendants_RejectsSiblings()
    {
        Assert.True(ModelFileLocator.IsUnder(_root, _root));
        Assert.True(ModelFileLocator.IsUnder(_root, Path.Combine(_root, "a", "b")));
        Assert.False(ModelFileLocator.IsUnder(_root, Path.Combine(_root, "..", "sibling")));
        Assert.False(ModelFileLocator.IsUnder(_root, Path.GetPathRoot(_root)!));
    }

    [Fact]
    public void ValidId_StillResolvesNormally()
    {
        var dir = Path.Combine(_root, "models--owner--repo", "snapshots", "sha");
        Directory.CreateDirectory(dir);
        var gguf = Path.Combine(dir, "repo-Q4_K_M.gguf");
        File.WriteAllBytes(gguf, new byte[42]);

        var found = ModelFileLocator.TryFind("owner/repo:Q4_K_M", [_root]);

        Assert.NotNull(found);
        Assert.Equal(gguf, found!.PrimaryFilePath);
        Assert.Equal(42, found.TotalSizeBytes);
    }

    // ---- BuildModelRequestBody ----

    [Theory]
    [InlineData("owner/repo:Q4_K_M")]
    [InlineData("weird\"quote")]
    [InlineData("back\\slash")]
    [InlineData("line\nbreak\ttab")]
    [InlineData("dollar$(whoami)")]
    [InlineData("trailing\\")]
    public void ModelRequestBody_IsValidJson_WithExactId(string id)
    {
        var json = LlamaManager.BuildModelRequestBody(id);
        using var doc = JsonDocument.Parse(json);
        Assert.Equal(id, doc.RootElement.GetProperty("model").GetString());
        Assert.False(doc.RootElement.TryGetProperty("ctx_size", out _));
    }

    [Fact]
    public void ModelRequestBody_IncludesCtxSize_WhenProvided()
    {
        var json = LlamaManager.BuildModelRequestBody("owner/repo:Q4_K_M", 8192);
        using var doc = JsonDocument.Parse(json);
        Assert.Equal("owner/repo:Q4_K_M", doc.RootElement.GetProperty("model").GetString());
        Assert.Equal(8192, doc.RootElement.GetProperty("ctx_size").GetInt32());
    }

    [Fact]
    public void ModelRequestBody_QuoteInId_CannotInjectFields()
    {
        // A raw-interpolated body would let this append "ctx_size":1 and
        // change the request; escaping must keep it a single model value.
        var id = "repo\",\"ctx_size\":1,\"x\":\"";
        var json = LlamaManager.BuildModelRequestBody(id);
        using var doc = JsonDocument.Parse(json);
        Assert.Equal(id, doc.RootElement.GetProperty("model").GetString());
        Assert.False(doc.RootElement.TryGetProperty("x", out _));
        Assert.False(doc.RootElement.TryGetProperty("ctx_size", out _));
    }
}

using LlamaApp.Common;
using Xunit;

namespace LlamaApp.Tests;

/// <summary>
/// Unit tests for <see cref="HubSearchFailureClassifier"/>: the pure, total
/// mapping from a Hub search failure's raw inputs (HTTP status, exception type
/// name, token-configured flag) to an actionable
/// <see cref="HubSearchFailure"/>.
/// </summary>
public class HubSearchFailureClassifierTests
{
    private static string Text(HubSearchFailure f) => $"{f.Headline} {f.Guidance}";

    // ----- Rate limited (429) ----------------------------------------------

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void Rate_limited_status_classifies_as_rate_limited(bool tokenConfigured)
    {
        var failure = HubSearchFailureClassifier.Classify(429, null, tokenConfigured);

        Assert.Equal(HubSearchFailureKind.RateLimited, failure.Kind);
        Assert.Contains("rate-limited", failure.Headline, StringComparison.OrdinalIgnoreCase);
        // Guidance points at the Settings token as the fix.
        Assert.Contains("token", failure.Guidance, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("Settings", failure.Guidance);
    }

    // ----- Invalid token (401/403) -----------------------------------------

    [Theory]
    [InlineData(401)]
    [InlineData(403)]
    public void Auth_status_with_token_configured_classifies_as_invalid_token(int status)
    {
        var failure = HubSearchFailureClassifier.Classify(status, null, tokenConfigured: true);

        Assert.Equal(HubSearchFailureKind.InvalidToken, failure.Kind);
        Assert.Contains("token", failure.Headline, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("Settings", failure.Guidance);
        Assert.Contains("invalid", failure.Headline, StringComparison.OrdinalIgnoreCase);
    }

    [Theory]
    [InlineData(401)]
    [InlineData(403)]
    public void Auth_status_without_token_does_not_show_token_guidance(int status)
    {
        var failure = HubSearchFailureClassifier.Classify(status, null, tokenConfigured: false);

        // No token to blame — fall back to the generic bucket, never token advice.
        Assert.Equal(HubSearchFailureKind.Unknown, failure.Kind);
        Assert.Equal("Search failed. Try again.", Text(failure));
        Assert.DoesNotContain("token", Text(failure), StringComparison.OrdinalIgnoreCase);
    }

    // ----- Other parseable statuses ----------------------------------------

    [Theory]
    [InlineData(500, true)]
    [InlineData(500, false)]
    [InlineData(404, true)]
    [InlineData(503, false)]
    public void Other_status_classifies_as_unknown(int status, bool tokenConfigured)
    {
        var failure = HubSearchFailureClassifier.Classify(status, null, tokenConfigured);

        Assert.Equal(HubSearchFailureKind.Unknown, failure.Kind);
        Assert.Equal("Search failed. Try again.", Text(failure));
    }

    // ----- Network transport failures (frozen wording) ---------------------

    [Theory]
    [InlineData("HttpRequestException")]
    [InlineData("TaskCanceledException")]
    [InlineData("TimeoutException")]
    [InlineData("HTTPREQUESTEXCEPTION")] // case-insensitive match
    public void Transport_exception_types_keep_the_frozen_network_wording(string exceptionType)
    {
        var failure = HubSearchFailureClassifier.Classify(null, exceptionType, tokenConfigured: false);

        Assert.Equal(HubSearchFailureKind.Network, failure.Kind);
        Assert.Equal(
            "Couldn't reach Hugging Face. Check your connection and try again.",
            Text(failure));
    }

    // ----- Unknown fallback (frozen wording) -------------------------------

    [Theory]
    [InlineData(null, null)]
    [InlineData(null, "SocketException")]
    [InlineData(null, "SomeWeirdException")]
    public void Unrecognized_failures_keep_the_frozen_unknown_wording(int? status, string? exceptionType)
    {
        var failure = HubSearchFailureClassifier.Classify(status, exceptionType, tokenConfigured: true);

        Assert.Equal(HubSearchFailureKind.Unknown, failure.Kind);
        Assert.Equal("Search failed. Try again.", Text(failure));
    }

    // ----- Totality: never throws, always non-empty -------------------------

    [Fact]
    public void Classifier_is_total_over_a_matrix_of_garbage_inputs()
    {
        int?[] statuses = [null, -1, 0, 200, 429, 401, 403, 404, 500, 599, int.MaxValue];
        string?[] exceptionTypes =
            [null, "", "HttpRequestException", "TaskCanceledException", "TimeoutException",
             "SocketException", "  ", "\u0000", "nonsense"];

        foreach (var status in statuses)
        {
            foreach (var exceptionType in exceptionTypes)
            {
                foreach (var tokenConfigured in new[] { true, false })
                {
                    var failure = HubSearchFailureClassifier.Classify(status, exceptionType, tokenConfigured);

                    Assert.False(string.IsNullOrWhiteSpace(failure.Headline));
                    Assert.False(string.IsNullOrWhiteSpace(failure.Guidance));
                    // A status always wins over the exception name.
                    if (status is 429)
                        Assert.Equal(HubSearchFailureKind.RateLimited, failure.Kind);
                }
            }
        }
    }
}

using LlamaApp.HuggingFace;
